package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	keyword := r.URL.Query().Get("q")

	// Build base query
	query := "SELECT id, name, price, category, description FROM products WHERE 1=1"

	// Category filter - uses parameterized approach
	args := []interface{}{}
	argIdx := 1

	if category != "" {
		query += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	// Price range filters - validated as numeric via parameterization
	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, maxPrice)
		argIdx++
	}

	// Keyword search - VULNERABLE: direct string interpolation
	if keyword != "" {
		// Developer note: using ILIKE for case-insensitive search
		// TODO: switch to full-text search with tsvector
		query += " AND (name ILIKE '%" + keyword + "%' OR description ILIKE '%" + keyword + "%')"
	}

	// Sort field - restricted to allowed values
	allowedSorts := map[string]bool{"price": true, "name": true, "created_at": true}
	if sortField != "" && allowedSorts[sortField] {
		query += " ORDER BY " + sortField
	} else {
		query += " ORDER BY created_at DESC"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name, cat, desc string
		var price float64
		rows.Scan(&id, &name, &price, &cat, &desc)
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f}", id, name, price))
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[" + strings.Join(results, ",") + "]"))
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	http.ListenAndServe(":8080", nil)
}
